"""Cache stable manifests without retaining classes generated per compilation."""

from functools import lru_cache, wraps
from inspect import signature
from typing import Callable, TypeVar

T = TypeVar("T")


def is_dynamic_manifest(manifest_type: type) -> bool:
    """Identify manifests generated by the dynamic block compiler.

    Args:
        manifest_type: Manifest class being inspected.

    Returns:
        Whether the class belongs to a dynamic block.
    """
    dynamic = getattr(manifest_type, "__workflow_dynamic_manifest__", False)

    return dynamic


def cache_static_manifest(*, maxsize: int) -> Callable:
    """Apply an LRU cache only to stable manifest classes.

    The decorated function must take exactly one manifest-class argument.
    Both positional and keyword calls and the LRU inspection/clear methods
    are preserved. Dynamic classes are never inserted into the global cache.

    Args:
        maxsize: Maximum number of static manifest entries to retain.

    Returns:
        Decorator for a single-argument manifest inspection function.
    """

    def decorate(function: Callable[..., T]) -> Callable[..., T]:
        argument_name = next(iter(signature(function).parameters))
        cached = lru_cache(maxsize=maxsize)(function)

        @wraps(function)
        def wrapper(*args, **kwargs) -> T:
            manifest_type = args[0] if args else kwargs[argument_name]
            if is_dynamic_manifest(manifest_type):
                result = function(*args, **kwargs)
            else:
                result = cached(*args, **kwargs)

            return result

        wrapper.cache_clear = cached.cache_clear
        wrapper.cache_info = cached.cache_info
        wrapper.cache_parameters = cached.cache_parameters
        return wrapper

    return decorate
